

# This file was *autogenerated* from the file exp1_correctness.sage
from sage.all_cmdline import *   # import sage library

_sage_const_128 = Integer(128); _sage_const_256 = Integer(256); _sage_const_512 = Integer(512); _sage_const_1024 = Integer(1024); _sage_const_2048 = Integer(2048); _sage_const_10 = Integer(10); _sage_const_100 = Integer(100); _sage_const_12345 = Integer(12345); _sage_const_0 = Integer(0); _sage_const_2 = Integer(2); _sage_const_1 = Integer(1)# =============================================================================
# Experiment 1 -- Correctness
#   (a) On weak keys (d < n^(1/4)/3) the attack must succeed 100% of the time.
#   (b) On standard keys (e = 65537) the attack must fail (negative control).
# Output: results/exp1_correctness.csv
# Run:    sage exp1_correctness.sage [--quick]
# =============================================================================
import sys
load("wiener_lib.sage")

QUICK  = "--quick" in sys.argv
SIZES  = [_sage_const_128 , _sage_const_256 , _sage_const_512 , _sage_const_1024 ] if QUICK else [_sage_const_128 , _sage_const_256 , _sage_const_512 , _sage_const_1024 , _sage_const_2048 ]
TRIALS = _sage_const_10  if QUICK else _sage_const_100 
SEED   = _sage_const_12345 
set_random_seed(SEED)

rows = []
print(f"{'bits':>6} {'key type':>10} {'trials':>7} {'recovered':>10} {'rate':>7}")
for bits in SIZES:
    for key_type, keygen in (("weak", generate_weak_key),
                             ("standard", generate_standard_key)):
        recovered = _sage_const_0 
        for _ in range(TRIALS):
            n, e, d, p, q = keygen(bits)
            res = wiener_attack(e, n)
            good = is_correct_recovery(res, d, p, q)
            if good:
                # Extra end-to-end check: the recovered d really decrypts.
                m = ZZ.random_element(_sage_const_2 , n - _sage_const_1 )
                good = power_mod(power_mod(m, e, n), res[_sage_const_0 ], n) == m
            recovered += int(good)
        rate = recovered / TRIALS
        print(f"{bits:>6} {key_type:>10} {TRIALS:>7} {recovered:>10} {float(rate):>7.2f}")
        rows.append(dict(bits=bits, key_type=key_type, trials=TRIALS,
                         recovered=recovered, success_rate=float(rate)))

write_csv("results/exp1_correctness.csv",
          ["bits", "key_type", "trials", "recovered", "success_rate"], rows)

